export function resolveStaticDealerVoiceUrl(styleId: string, cleanText: string): string | null {
  return (
    DEALER_VOICE_MANIFEST[`${styleId}::${cleanText}`] ??
    DEALER_VOICE_MANIFEST[`_shared::${cleanText}`] ??
    null
  );
}
